-- quest rewards / xp (World/Quests.lua has the texts and objectives)
D.quests = {}
D.quests[6] = { lvl = 5, xpm = 210, choice = { { 6076, 1 }, { 60, 1 }, { 3070, 1 } }, offer = "Hah - you caught him! You've done Elwynn a great service, and earned a nice bounty!", req = "Did you find Garrick's shack? Are we finally free of that villain?", flags = 8, zone = "Northshire Valley" }
D.quests[7] = { lvl = 2, xpm = 90, money = 25, offer = "Well done, citizen. Those kobolds are thieves and cowards, but in large numbers they pose a threat to us. And the humans of Stormwind do not need another threat.$B$BFor defeating them, you have my gratitude.", req = "How goes the hunting, $N? Have you found and defeated those vermin?", flags = 8, zone = "Northshire Valley" }
D.quests[15] = { lvl = 3, xpm = 150, money = 40, offer = "I don't like hearing of all these kobolds in our mine. No good can come of this. Here, take this as payment, and when you're ready, speak to me again. I would like you to go back to the mines one more time...", req = "Have you been to the mines? Are you ready to report?", flags = 8, next = 21, zone = "Northshire Valley" }
D.quests[18] = { lvl = 4, xpm = 210, choice = { { 2224, 1 }, { 5580, 1 }, { 1161, 1 }, { 5579, 1 }, { 1159, 1 } }, offer = "Back with some bandanas, I see. The Stormwind Army appreciates your help.", req = "Have you gathered those bandanas for me yet?", flags = 8, zone = "Northshire Valley" }
D.quests[21] = { lvl = 5, xpm = 270, choice = { { 2186, 1 }, { 2691, 1 }, { 11192, 1 } }, offer = "Once again, you have earned my respect, and the gratitude of the Stormwind Army. There may yet be kobolds in the mine, but I will marshal others against them. We have further tasks for you.", req = "I know it's bloody work, $N, but it's vital to the safety of Northshire. Are you ready to report?", flags = 8, zone = "Northshire Valley" }
D.quests[33] = { lvl = 2, xpm = 90, choice = { { 80, 1 }, { 6070, 1 } }, offer = "You've been busy! I can't wait to cook up that wolf meat...$B$BI have some things here you want - take your pick!", req = "Hey $N. I'm getting hungry...did you get that tough wolf meat?", flags = 8, zone = "Northshire Valley" }
D.quests[54] = { lvl = 5, xpm = 120, rew = { { 6078, 1 } }, src = { 745, 1 }, offer = "Well, it says here that you've been awarded Acting Deputy Status with the Stormwind Marshals. Congratulations.$b$bAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!$b$bIt's hard to keep track of politics in these dark days...", req = "You have word from McBride? Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.$b$bHere, let me have his papers...", zone = "Northshire Valley" }
D.quests[344] = { lvl = 24, xpm = 300, offer = "Mr. Sheaf is wondering where his book is? Well this is a tad embarrassing. I have the book, but I'm still making my copy and I'm not quite ready to give the original up!", flags = 8, next = 345, zone = "Stormwind City" }
D.quests[345] = { lvl = 24, xpm = 300, offer = "You need what?? Maybe you haven't noticed, but we're busy fortifying Lakeshire's defenses and repairing damage from recent orc attacks. If you need Rethban Iron Ore, you'll have to get it yourself!", flags = 8, next = 347, zone = "Stormwind City" }
D.quests[346] = { lvl = 24, xpm = 1200, rew = { { 6095, 1 } }, src = { 2795, 1 }, offer = "That's the one! Thank you, $N. May the Light shine brightly upon both your body and spirit!", req = "Were you able to find the book?", zone = "Stormwind City" }
D.quests[347] = { lvl = 24, xpm = 570, offer = "Oh, splendid! I can use this ore to make my dye, and then can finish copying The Stresses of Iron.$B$BThank you, $N!", req = "Do you have the Rethban Ore?", flags = 8, next = 346, zone = "Stormwind City" }
D.quests[783] = { lvl = 1, xpm = 30, offer = "Ah, good.  Another volunteer.  We're getting a lot of you these days.$B$BI hope it's enough.$B$BThe human lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.$B$BIt is a many-fronted battle we wage, $N.  Gird yourself for a long campaign.", flags = 8, next = 7, zone = "Northshire Valley" }
D.quests[1598] = { lvl = -1, spell = 7763, offer = "Excellent... I was never able to gain access to this text, it was held in a protected wing of the library that would have looked suspicious for me to be loitering around.$B$BWell, you did a good job in getting this, and I'm convinced that you can probably handle your own imp, so there's no reason for me not to show you how to summon one.", req = "It was too conspicuous for me to steal the book myself. What luck one of their own patsies did the dirty work for me.", flags = 8 }
D.quests[2158] = { lvl = 5, xpm = 60, choice = { { 4656, 5 }, { 159, 5 } }, offer = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.$B$BWould you like to try a sampling of some of our fine food and drink?", flags = 8, zone = "Elwynn Forest" }
D.quests[3100] = { lvl = 1, xpm = 30, src = { 9542, 1 }, offer = "Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I'll be here night or day.$B$BThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you'll find they all have problems they could use some help with--help a warrior can give them. Good luck.", req = "Ah, you got my letter, $N... good.$B$BThere's been an influx of warriors in Elwynn recently - which is good for Stormwind, but bad for the kobolds and Defias in the area." }
D.quests[3101] = { lvl = 1, xpm = 30, src = { 9570, 1 }, offer = "In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.$B$BAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That's where I come in. When you feel you've gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... $C!", req = "Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand." }
D.quests[3102] = { lvl = 1, xpm = 24, src = { 9555, 1 }, offer = "You're gonna find that there a number of outfits that'll covet our skills, $N. Adventurers, SI:7... heck, even the Defias Brotherhood wouldn't mind a spy or two inside Stormwind. But you remember this, you're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?$B$BAnyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime.", req = "You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.$b$bHave any trouble yet? I'm glad to hear not. That'll change soon enough." }
D.quests[3103] = { lvl = 1, xpm = 30, src = { 9548, 1 }, offer = "As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so.", req = "Ah, at last you've come. I knew you would find your way to me. The Holy Light shines upon you, and the path you've chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can." }
D.quests[3104] = { lvl = 1, xpm = 30, src = { 9571, 1 }, offer = "Haha, I knew my note would not dissuade you from your path. So, you're prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?$B$BI will not lie, $N, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful.", req = "Hello, $N. I am Khelden. Is there something I can do for you?" }
D.quests[3105] = { lvl = 1, xpm = 30, src = { 9576, 1 }, offer = "As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.$B$BAs you grow more powerful, return to me and I will teach you more about our ways.", req = "Ah, so you've arrived, and not a moment too soon, $N. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes." }
D.quests[3903] = { lvl = 4, xpm = 30, offer = "Oh, Deputy Willem told you to speak with me? He's a brave man and always willing to help, but his duties keep him stuck at Northshire Abbey and I'm afraid the problem I have today is beyond him.$b$bPerhaps you can help me?", flags = 8, next = 3904, zone = "Northshire Valley" }
D.quests[3904] = { lvl = 4, xpm = 120, offer = "Oh thank you, $N! You saved my harvest! And I hope you showed a few of those Defias that they can't cause trouble around here.$b$bWe might be short on guards these days, but we're lucky to have heroes like you to protect us!", req = "Do you have my harvest, $N?", flags = 8, next = 3905, zone = "Northshire Valley" }
D.quests[3905] = { lvl = 4, xpm = 210, choice = { { 11475, 1 }, { 2690, 1 } }, src = { 11125, 1 }, offer = "Let's see here...$b$bOh my! Milly's grapes have been saved! When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!$b$bAnd through your bravery, we now have grapes for more wine! May the Light bless you, $N, and keep you safe!", req = "You look to be in fine spirits! Come! Have a seat, and have a drink!", zone = "Northshire Valley" }
D.quests[5261] = { lvl = 2, xpm = 60, offer = "That's true.  I'm looking for someone to hunt me some wolves!  Are you that person?", flags = 8, next = 33, zone = "Northshire Valley" }
D.quests[5623] = { lvl = 4, xpm = 54, offer = "I'm glad you've arrived, $N. We have much to discuss about your future and your path within the Light.", flags = 8, next = 5624 }
D.graveyards = { { x = 4141.28, y = 6240.48, n = "Elwynn Forest, Northshire" } }
